create or replace function private.current_role_code() returns text language sql stable security definer set search_path = '' as $$ select r.code from public.profiles p join public.roles r on r.id = p.role_id where p.id = (select auth.uid()) and p.is_active = true limit 1; $$;
create or replace function private.is_teacher() returns boolean language sql stable security definer set search_path = '' as $$ select coalesce((select private.current_role_code()) in ('teacher','admin'), false); $$;
create or replace function private.is_admin() returns boolean language sql stable security definer set search_path = '' as $$ select coalesce((select private.current_role_code()) = 'admin', false); $$;
create or replace function private.is_class_teacher(p_class_id uuid) returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from public.classes c where c.id = p_class_id and c.teacher_id = (select auth.uid())) or (select private.is_admin()); $$;
create or replace function private.is_student_in_class(p_class_id uuid, p_student_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from public.class_members cm where cm.class_id = p_class_id and cm.student_id = p_student_id and cm.status = 'active'); $$;
create or replace function private.is_teacher_of_student(p_student_id uuid) returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from public.classes c join public.class_members cm on cm.class_id = c.id where c.teacher_id = (select auth.uid()) and cm.student_id = p_student_id and cm.status = 'active') or (select private.is_admin()); $$;
revoke execute on function private.current_role_code() from public, anon; revoke execute on function private.is_teacher() from public, anon; revoke execute on function private.is_admin() from public, anon; revoke execute on function private.is_class_teacher(uuid) from public, anon; revoke execute on function private.is_student_in_class(uuid, uuid) from public, anon; revoke execute on function private.is_teacher_of_student(uuid) from public, anon; grant usage on schema private to authenticated; grant execute on function private.current_role_code() to authenticated; grant execute on function private.is_teacher() to authenticated; grant execute on function private.is_admin() to authenticated; grant execute on function private.is_class_teacher(uuid) to authenticated; grant execute on function private.is_student_in_class(uuid, uuid) to authenticated; grant execute on function private.is_teacher_of_student(uuid) to authenticated;;
